def text_width(text, size):
    return sum(size if ord(ch) > 0x2E80 else size * 0.56 for ch in text)


def shape(name, x, y, size, fill, rotate=0):
    s = size / 100
    cx, cy = x + size / 2, y + size / 2
    rot = f"rotate({rotate} {cx:.1f} {cy:.1f}) " if rotate else ""
    return (
        f'<path transform="{rot}translate({x:.1f} {y:.1f}) scale({s:.4f})" '
        f'd="{SHAPES[name]}" fill="{fill}"/>'
    )


def text(x, y, content, size, fill, weight=400, anchor="start"):
    return (
        f'<text x="{x:.1f}" y="{y:.1f}" font-family="{FONT}" font-size="{size}" '
        f'font-weight="{weight}" fill="{fill}" text-anchor="{anchor}">{content}</text>'
    )


def svg(width, height, body, label):
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width:.0f}" height="{height:.0f}" '
        f'viewBox="0 0 {width:.0f} {height:.0f}" role="img" aria-label="{label}">\n'
        f"<title>{label}</title>\n{body}\n</svg>\n"
    )


def pill(label, icon, bg, fg, icon_fill, height=64, size=26):
    width = 14 + 36 + 14 + text_width(label, size) + 30
    body = "\n".join([
        f'<rect width="{width:.0f}" height="{height}" rx="{height / 2}" fill="{bg}"/>',
        shape(icon, 14, (height - 36) / 2, 36, icon_fill),
        text(64, height / 2 + size * 0.36, label, size, fg, 700),
    ])
    return svg(width, height, body, label)


def section_title(p, label, icon, height=64, size=28):
    width = 44 + 14 + text_width(label, size) + 4
    body = "\n".join([
        shape(icon, 0, (height - 44) / 2, 44, p["accent"]),
        text(58, height / 2 + size * 0.36, label, size, p["title"], 700),
    ])
    return svg(width, height, body, label)


def button(p, label, icon, kind):
    return pill(label, icon, p[f"{kind}_bg"], p[f"{kind}_text"], p[f"{kind}_icon"], height=60, size=24)


def feature_card(p, key, title, icon, badge, lines):
    w, h = 460, 230
    parts = [
        f'<defs><clipPath id="c-{key}"><rect width="{w}" height="{h}" rx="32"/></clipPath></defs>',
        f'<rect width="{w}" height="{h}" rx="32" fill="{p["card"]}"/>',
        f'<g clip-path="url(#c-{key})">{shape(icon, 300, 96, 220, p["deco"], rotate=18)}</g>',
        shape(icon, 30, 28, 64, p["accent"]),
        text(30, 136, title, 28, p["title"], 700),
    ]
    if badge:
        bw = text_width(badge, 15) + 28
        parts += [
            f'<rect x="{w - 30 - bw:.1f}" y="38" width="{bw:.1f}" height="32" rx="16" fill="{p["chip_bg"]}"/>',
            text(w - 30 - bw / 2, 59, badge, 15, p["chip_text"], 700, "middle"),
        ]
    for i, line in enumerate(lines):
        parts.append(text(30, 172 + i * 30, line, 18, p["body"]))
    return svg(w, h, "\n".join(parts), title)


def screenshots(p):
    pw, ph, gap, pad = 240, 507, 36, 30
    w = pad * 2 + pw * len(SCREENSHOTS) + gap * (len(SCREENSHOTS) - 1)
    h = pad + ph + 64
    icons = ["Puffy", "Slanted", "PuffyDiamond", "Pentagon"]
    parts = []
    for i, caption in enumerate(SCREENSHOTS):
        x = pad + i * (pw + gap)
        parts += [
            f'<rect x="{x}" y="{pad}" width="{pw}" height="{ph}" rx="36" fill="{p["card"]}"/>',
            shape(icons[i], x + (pw - 120) / 2, pad + ph / 2 - 90, 120, p["deco"], rotate=i * 12),
            text(x + pw / 2, pad + ph / 2 + 74, "截图待补充", 18, p["body"], 400, "middle"),
            text(x + pw / 2, pad + ph + 44, caption, 22, p["title"], 700, "middle"),
        ]
    return svg(w, h, "\n".join(parts), "截图预览")


def main():
    import os

    out = os.path.dirname(os.path.abspath(__file__))
    files = {}
    for mode, p in PALETTES.items():
        for key, label, icon in SECTIONS:
            files[f"title-{key}-{mode}.svg"] = section_title(p, label, icon)
        for key, title, icon, badge, lines in FEATURES:
            files[f"feature-{key}-{mode}.svg"] = feature_card(p, key, title, icon, badge, lines)
        for key, label, icon, kind in BUTTONS:
            files[f"button-{key}-{mode}.svg"] = button(p, label, icon, kind)
        files[f"screenshots-{mode}.svg"] = screenshots(p)
    for name, content in files.items():
        with open(os.path.join(out, name), "w", encoding="utf-8", newline="\n") as f:
            f.write(content)
    print(f"generated {len(files)} files")


if __name__ == "__main__":
    main()
